"""Hash-bound Python3.10 compatibility repair; never loads or launches a model."""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import sys
import uuid

CONFIG = {'original_protocol_sha256': 'e1e4b9fd8c4bf71db806deca03a66e187e9726cafff65ff799acc25aa432387e', 'new_protocol_sha256': 'e79183a9f4e3ea50e9ac1d6705d9667f046364132e1f1be0628befd024835d9a', 'repair_files': [{'path': 'scripts/cctv_completion_codeformer_gradient_v1_vm.py', 'old': {'bytes': 18856, 'sha256': 'bdafe1e6f743c15642c721d1813deae64f9d6abcf8cc229387a6b3cad95bf791'}, 'new': {'bytes': 18959, 'sha256': 'd3c082f78c1a70ca2bb8e134da9c673155766efc88922857c838e633d4e20f69'}}, {'path': 'scripts/export_completion_codeformer_gradient_v1.py', 'old': {'bytes': 4059, 'sha256': 'd47c728676dfb1e302ff246fdacc01544ad83af5e6b6fe1507f9cf59ede798dc'}, 'new': {'bytes': 4169, 'sha256': '534631dc73727afae5672ef8e7bf4e2f669a5688cd01f174f41a896d7b724831'}}], 'payload_base64': {'scripts/cctv_completion_codeformer_gradient_v1_vm.py': '', 'scripts/export_completion_codeformer_gradient_v1.py': '', 'protocol.json': ''}}
VM_NAME = 'cctv_completion_codeformer_gradient_v1_vm'

def need(ok,message):
    if not ok:raise ValueError(message)

def sha(path):
    digest=hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''):digest.update(block)
    return digest.hexdigest()

def member(root,name):
    need(isinstance(name,str) and name and '\\' not in name and ':' not in name and '\0' not in name,'Invalid repair member')
    parts=PurePosixPath(name)
    need(not parts.is_absolute() and all(x not in ('','.','..') for x in name.split('/')),'Repair traversal refused')
    path=root
    for part in parts.parts:
        path=path/part
        need(not path.is_symlink(),'Repair symlink refused')
    need(path.resolve().is_relative_to(root),'Repair member escaped root')
    need(path.is_file() and stat.S_ISREG(path.stat().st_mode),'Repair requires a regular existing file')
    return path

def verify_files(root,protocol):
    names=[row['path'] for row in protocol['files']]
    need(len(names)==len(set(names)),'Duplicate protocol file')
    for row in protocol['files']:
        path=member(root,row['path'])
        need(path.stat().st_size==row['bytes'] and sha(path)==row['sha256'],'Installed packet file changed: '+row['path'])

def write_new(path,data):
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('xb') as stream:
        stream.write(data);stream.flush();os.fsync(stream.fileno())

def apply(root,config=CONFIG):
    root=Path(root).resolve(strict=True)
    need(root.is_dir() and root.name==VM_NAME,'Use the exact installed completion diagnostic folder')
    protocol_path=member(root,'protocol.json')
    current=sha(protocol_path)
    if current==config['new_protocol_sha256']:
        verify_files(root,json.loads(protocol_path.read_text(encoding='utf-8')))
        return {'complete':True,'already_applied':True,'protocol_sha256':current,'files_changed':0,'neural_calls':0,'gradient_queries':0,'optimizer_updates':0}
    need(current==config['original_protocol_sha256'],'Installed protocol is not the admitted R1 packet; stop and retain it')
    for name in ('outputs','supervisor.json','diagnostic.log','failure.json'):
        need(not (root/name).exists(),'A diagnostic may have started; retain and audit its evidence before repair: '+name)
    original_protocol=protocol_path.read_bytes()
    protocol=json.loads(original_protocol.decode('utf-8'))
    verify_files(root,protocol)
    payload={name:base64.b64decode(value,validate=True)for name,value in config['payload_base64'].items()}
    allowed={'protocol.json'}|{row['path']for row in config['repair_files']}
    need(set(payload)==allowed,'Repair payload scope differs')
    need(hashlib.sha256(payload['protocol.json']).hexdigest()==config['new_protocol_sha256'],'Replacement protocol fingerprint differs')
    new_protocol=json.loads(payload['protocol.json'].decode('utf-8'))
    before_rows={row['path']:row for row in protocol['files']}
    after_rows={row['path']:row for row in new_protocol['files']}
    need(set(before_rows)==set(after_rows),'Protocol member namespace changed')
    changed={row['path']for row in config['repair_files']}
    for name in before_rows:
        if name not in changed:need(before_rows[name]==after_rows[name],'Unrelated source, weight or data binding changed')
    for row in config['repair_files']:
        need({key:before_rows[row['path']][key]for key in ('bytes','sha256')}==row['old'],'Original repair binding differs')
        need({key:after_rows[row['path']][key]for key in ('bytes','sha256')}==row['new'],'Replacement repair binding differs')
        need(len(payload[row['path']])==row['new']['bytes'] and hashlib.sha256(payload[row['path']]).hexdigest()==row['new']['sha256'],'Replacement source bytes differ')
    before_meta={key:value for key,value in protocol.items()if key!='files'}
    after_meta={key:value for key,value in new_protocol.items()if key not in ('files','python_compatibility_repair')}
    need(before_meta==after_meta,'Scientific protocol, cases, limits or gates changed')
    stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'-'+uuid.uuid4().hex[:8]
    backup=root.parent/(VM_NAME+'_python310_repair_'+stamp)
    backup.mkdir(exist_ok=False)
    originals={name:member(root,name).read_bytes()for name in allowed}
    expected_old={'protocol.json':config['original_protocol_sha256']}
    expected_old.update({row['path']:row['old']['sha256']for row in config['repair_files']})
    need(all(hashlib.sha256(data).hexdigest()==expected_old[name]for name,data in originals.items()),'Installed source changed before backup')
    for name,data in originals.items():write_new(backup/'original'/name,data)
    plan={'complete':False,'repair':'streaming-sha256-for-python310-v1','original_protocol_sha256':current,'new_protocol_sha256':config['new_protocol_sha256'],'backup':str(backup),'python':sys.version,'reported_error':'AttributeError: hashlib.file_digest during first R1 transfer hash','changes':config['repair_files'],'scientific_settings_unchanged':True,'no_execution_namespace_before_repair':True,'neural_calls':0,'gradient_queries':0,'optimizer_updates':0}
    write_new(backup/'repair_started.json',(json.dumps(plan,indent=2)+'\n').encode())
    temporary=[]
    try:
        for name in sorted(changed)+['protocol.json']:
            target=member(root,name)
            need(target.read_bytes()==originals[name],'Installed file changed during repair')
            tmp=target.with_name(target.name+'.python310-'+uuid.uuid4().hex+'.tmp')
            write_new(tmp,payload[name]);temporary.append(tmp)
            os.replace(tmp,target)
        need(sha(protocol_path)==config['new_protocol_sha256'],'Committed protocol differs')
        verify_files(root,new_protocol)
        plan['complete']=True
        write_new(backup/'repair_complete.json',(json.dumps(plan,indent=2)+'\n').encode())
        return {**plan,'already_applied':False,'protocol_sha256':config['new_protocol_sha256'],'files_changed':3}
    except BaseException as exc:
        rollback=[]
        for name,old in originals.items():
            target=root/name
            if target.is_file() and not target.is_symlink() and target.read_bytes() in (old,payload[name]):
                if target.read_bytes()!=old:
                    tmp=target.with_name(target.name+'.rollback-'+uuid.uuid4().hex+'.tmp')
                    write_new(tmp,old);os.replace(tmp,target)
                rollback.append(name)
        failure={**plan,'complete':False,'error':repr(exc),'rolled_back':rollback,'temporary_files_retained':[str(p)for p in temporary if p.exists()]}
        write_new(backup/'repair_failure.json',(json.dumps(failure,indent=2)+'\n').encode())
        raise

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--expected-sha',required=True)
    p.add_argument('--root',type=Path,default=Path.home()/'forensic-dgp'/VM_NAME)
    a=p.parse_args()
    need(sha(Path(__file__))==a.expected_sha,'Repair-script SHA256 differs; do not run it')
    print(json.dumps(apply(a.root),indent=2),flush=True)

if __name__=='__main__':main()
